/*
 * MNIST test payload for the bare-metal board benchmark.
 *
 * The binary files are generated by generate_mobilenet_mnist10k_payload.py.
 * Absolute paths are intentional: Vitis invokes the assembler from its build
 * directory rather than from the directory containing this source file.
 */

    .section .rodata.sigma_mnist10k_images, "a", %progbits
    .balign 64
    .global sigma_mnist10k_images
    .type sigma_mnist10k_images, %object
sigma_mnist10k_images:
    .incbin "../../datasets/mobilenet_mnist10k_bf16.bin"
    .size sigma_mnist10k_images, . - sigma_mnist10k_images

    .section .rodata.sigma_mnist10k_images_broken, "a", %progbits
    .balign 64
    .global sigma_mnist10k_images_broken
    .type sigma_mnist10k_images_broken, %object
sigma_mnist10k_images_broken:
    .incbin "../../datasets/mobilenet_mnist10k_broken_bf16.bin"
    .size sigma_mnist10k_images_broken, . - sigma_mnist10k_images_broken

    .section .rodata.sigma_mnist10k_images_poor, "a", %progbits
    .balign 64
    .global sigma_mnist10k_images_poor
    .type sigma_mnist10k_images_poor, %object
sigma_mnist10k_images_poor:
    .incbin "../../datasets/mobilenet_mnist10k_poor_bf16.bin"
    .size sigma_mnist10k_images_poor, . - sigma_mnist10k_images_poor

    .section .rodata.sigma_mnist10k_labels, "a", %progbits
    .balign 64
    .global sigma_mnist10k_labels
    .type sigma_mnist10k_labels, %object
sigma_mnist10k_labels:
    .incbin "../../datasets/mobilenet_mnist10k_labels.bin"
    .size sigma_mnist10k_labels, . - sigma_mnist10k_labels

    .section .note.GNU-stack, "", %progbits
